import { describe, expect, it, test } from "vitest";
import { MacrosType } from "@Types/macros";
import { parseMacrosRaw, serializeMacros } from "./macros";

describe("parseMacrosRaw", () => {
  it("GAP: throws out anything after the first ' 0 0'", () => {
    // This may be intended as the serializer only populates every memory value when you erase all macros.
    expect(parseMacrosRaw("8 22 0 0 8 22 0 0", [])).toEqual([
      { id: 0, name: "", actions: [{ keyCode: 22, type: 8 }], macro: "" },
    ]);
  });

  it("should ignore keys which don't have a base 10 code", () => {
    expect(parseMacrosRaw("8 F 8 22 0 0", [])).toEqual([{ id: 0, name: "", actions: [{ keyCode: 22, type: 8 }], macro: "" }]);
  });

  it("should ignore keys which don't have a base 10 type", () => {
    expect(parseMacrosRaw("F 22 8 22 0 0", [])).toEqual([{ id: 0, name: "", actions: [{ keyCode: 22, type: 8 }], macro: "" }]);
  });

  it("should treat a 0 as the end of a macro", () => {
    expect(parseMacrosRaw("8 22 0 8 40 0 0", [])).toEqual([
      { id: 0, name: "", actions: [{ keyCode: 22, type: 8 }], macro: "" },
      { id: 1, name: "", actions: [{ keyCode: 40, type: 8 }], macro: "" },
    ]);
  });

  it("GAP: Type 1 never makes it into the actions list", () => {
    expect(parseMacrosRaw("1 1 2 3 4 0 0", [])).toEqual([{ id: 0, name: "", actions: [], macro: "" }]);
  });

  test.each([{ type: 2 }, { type: 3 }, { type: 4 }, { type: 5 }])(
    "should parse key of type $type using the next 2 bytes",
    ({ type }) => {
      //    1 = 0b0000_0001
      // << 8 = 0b0000_0001_0000_0000
      //  + 2 = 0b0000_0001_0000_0010
      expect(parseMacrosRaw(`${type} 1 2 0 0`, [])).toEqual([
        { id: 0, name: "", actions: [{ keyCode: 0b0000_0001_0000_0010, type }], macro: "" },
      ]);
    },
  );

  it("GAP: Type 2-5 with values larger than 8 bits results in a larger than 16 bit number", () => {
    //   257 = 0b0001_0000_0001
    //  << 8 = 0b0001_0000_0001_0000_0000
    // + 257 = 0b0001_0000_0010_0000_0001
    expect(parseMacrosRaw("2 257 257 0 0", [])).toEqual([
      { id: 0, name: "", actions: [{ keyCode: 0b00001_0000_0010_0000_0001, type: 2 }], macro: "" },
    ]);
  });

  test.each([{ type: 6 }, { type: 7 }, { type: 8 }])("should parse key of type $type using the next 1 bytes", ({ type }) => {
    expect(parseMacrosRaw(`${type} 1 0 0`, [])).toEqual([{ id: 0, name: "", actions: [{ keyCode: 1, type }], macro: "" }]);
  });

  it("should skip types 9+ and carry on adding actions", () => {
    expect(parseMacrosRaw("9 2 1 2 0 0", [])).toEqual([
      { id: 0, name: "", actions: [{ keyCode: 0b0000_0001_0000_0010, type: 2 }], macro: "" },
    ]);
  });

  it("should filter out any keycode that isn't a number", () => {
    expect(parseMacrosRaw("9 6 1 6 a 6 2 0 0", [])).toEqual([
      {
        id: 0,
        name: "",
        actions: [
          { keyCode: 1, type: 6 },
          { keyCode: 2, type: 6 },
        ],
        macro: "",
      },
    ]);
  });

  it("should ignore last type if too few numbers remain to construct", () => {
    expect(parseMacrosRaw("6 1 4 2 0 0", [])).toEqual([
      {
        id: 0,
        name: "",
        actions: [{ keyCode: 1, type: 6 }],
        macro: "",
      },
    ]);
  });

  it("GAP: types 6-8 keyCode will be undefined if byte could not be read", () => {
    expect(parseMacrosRaw("6 0 0", [])).toEqual([
      {
        id: 0,
        name: "",
        actions: [{ keyCode: undefined, type: 6 }],
        macro: "",
      },
    ]);
  });

  it("GAP: 'macro' is only populated if `storedMacros` is not empty", () => {
    const noneStored: MacrosType[] = [];
    expect(parseMacrosRaw(`6 1 0 0`, noneStored)[0].macro).toEqual("");

    const oneStored: MacrosType[] = [{ actions: [], name: "abc", macro: "def" }];
    expect(parseMacrosRaw(`6 1 0 0`, oneStored)[0].macro).toEqual("#1");
  });

  it("GAP: 'name' is only populated based on index position from `storedMacros` not by actions", () => {
    const oneStored: MacrosType[] = [{ actions: [], name: "abc", macro: "def" }];
    expect(parseMacrosRaw(`6 1 0 0`, oneStored)[0].name).toEqual("abc");
  });

  it("should parse demo macro", () => {
    // If "GAP: throws out anything after the first ' 0 0'" is a bug, then this input would contain 4 macros
    const data =
      "8 44 6 225 8 11 7 225 8 8 8 28 8 54 8 44 6 225 8 7 7 225 8 28 8 10 8 16 8 4 8 23 8 8 8 22 0 0 225 8 8 8 28 8 54 8 44 6 225 8 7 7 225 8 28 8 10 8 16 8 4 8 23 8 8 8 22 0 0 79 7 227 0 6 227 8 80 7 227 8 84 8 5 8 24 8 15 8 15 8 8 8 23 8 8 8 7 8 44 8 15 8 12 8 22 8 23 8 40 0 6 227 8 80 7 227 8 84 8 5 8 4 8 17 8 17 8 8 8 21 8 44 8 28 8 8 8 15 8 15 8 18 8 26 8 40 0 6 227 8 80 7 227 8 84 8 11 8 32 8 40 6 227 8 79 7 227 0 6 227 8 80 7 227 8 84 8 11 8 33 8 40 6 227 8 79 7 227 0 6 227 8 80 7 227 8 84 8 6 8 11 8 8 8 6 8 14 8 15 8 12 8 22 8 23 8 40 0 6 227 8 80 7 227 8 84 8 5 8 4 8 17 8 17 8 8 8 21 8 44 8 10 8 21 8 8 8 8 8 17 8 40 6 227 8 79 7 227 0 6 227 8 80 7 227 8 84 8 5 8 4 8 17 8 17 8 8 8 21 8 44 8 21 8 8 8 7 8 40 6 227 8 79 7 227 0 6 227 8 80 7 227 8 84 8 5 8 4 8 17 8 17 8 8 8 21 8 44 8 5 8 15 8 24 8 8 8 40 6 227 8 79 7 227 0 8 84 8 10 8 12 8 19 8 11 8 28 2 0 200 8 40 0 0 8 10 8 21 8 8 8 8 8 17 8 40 0 8 84 8 5 8 4 8 17 8 17 8 8 8 21 8 44 8 21 8 8 8 7 8 40 0 0 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 255 ";

    expect(
      parseMacrosRaw(data, [
        { id: 0, name: "first", actions: [], macro: "" },
        {
          id: 1,
          name: "second",
          actions: [],
          macro: "",
        },
      ]),
    ).toEqual([
      {
        actions: [
          { keyCode: 44, type: 8 },
          { keyCode: 225, type: 6 },
          { keyCode: 11, type: 8 },
          {
            keyCode: 225,
            type: 7,
          },
          { keyCode: 8, type: 8 },
          { keyCode: 28, type: 8 },
          { keyCode: 54, type: 8 },
          { keyCode: 44, type: 8 },
          {
            keyCode: 225,
            type: 6,
          },
          { keyCode: 7, type: 8 },
          { keyCode: 225, type: 7 },
          { keyCode: 28, type: 8 },
          { keyCode: 10, type: 8 },
          {
            keyCode: 16,
            type: 8,
          },
          { keyCode: 4, type: 8 },
          { keyCode: 23, type: 8 },
          { keyCode: 8, type: 8 },
          { keyCode: 22, type: 8 },
        ],
        id: 0,
        macro: "SPACE SHIFT H SHIFT E Y , SPACE SHIFT D SHIFT Y G M A T E S",
        name: "first",
      },
    ]);
  });
});

describe("serializeMacrosRaw", () => {
  it("should create a string containing 255 `tMem` times", () => {
    expect(serializeMacros([], 5)).toEqual("255 255 255 255 255");
  });

  it("should serialize a macro with a type 1", () => {
    const macros: MacrosType[] = [
      { id: 0, name: "", actions: [{ keyCode: [0b0000_0001_0000_0010, 0b0001_0000_0010_0000], type: 1 }], macro: "" },
    ];
    expect(serializeMacros(macros, 100)).toEqual("1 1 2 16 32 0 0");
  });

  it("GAP: serializing type 1 key code more than 16 bits results in a first number larger than 8-bit", () => {
    const macros: MacrosType[] = [
      { id: 0, name: "", actions: [{ keyCode: [0b0001_0000_0001_0000_0010, 0b0001_0001_0000_0010_0000], type: 1 }], macro: "" },
    ];
    expect(serializeMacros(macros, 100)).toEqual("1 257 2 272 32 0 0");
  });

  test.each([{ type: 2 }, { type: 3 }, { type: 4 }, { type: 5 }])("should serialize macro with type $type", ({ type }) => {
    const macros: MacrosType[] = [{ id: 0, name: "", actions: [{ keyCode: 0b0000_0001_0000_0010, type }], macro: "" }];
    expect(serializeMacros(macros, 100)).toEqual(`${type} 1 2 0 0`);
  });

  it("GAP: serializing type 2-5 key code more than 16 bits results in a first number larger than 8-bit", () => {
    const macros: MacrosType[] = [{ id: 0, name: "", actions: [{ keyCode: 0b0001_0000_0001_0000_0010, type: 2 }], macro: "" }];
    expect(serializeMacros(macros, 100)).toEqual("2 257 2 0 0");
  });

  test.each([{ type: 6 }, { type: 7 }, { type: 8 }])("should serialize macro with type $type", ({ type }) => {
    const macros: MacrosType[] = [{ id: 0, name: "", actions: [{ keyCode: 0b0000_0001_0000_0010, type }], macro: "" }];
    expect(serializeMacros(macros, 100)).toEqual(`${type} 258 0 0`);
  });
});
